<?php if ($orders): ?><div class="tbl-wrap"><table class="tbl"><thead><tr><th>N°</th><th>Date</th><th>Statut</th><th>Paiement</th><th class="right">Total</th><th></th></tr></thead><tbody><?php foreach ($orders as $o): ?><tr><td><b><?= e($o['ref']) ?></b></td><td><?= fdate($o['created_at']) ?></td><td><?= order_badge_public((string) $o['status']) ?></td><td><?= ['pending' => 'En attente', 'declared' => 'À vérifier', 'paid' => 'Payé', 'refunded' => 'Remboursé'][$o['payment_status']] ?></td><td class="right"><?= money($o['total']) ?></td><td><a class="btn btn-p btn-sm" href="/commande/<?= e($o['ref']) ?>">Détails</a></td></tr><?php endforeach; ?></tbody></table></div>
<?php else: ?><div class="panel center"><p class="muted">Aucune commande pour le moment.</p><a class="btn btn-a" href="/catalogue">Voir le catalogue</a></div><?php endif; ?>
